  "hygiene.Noncharacter",
  "presence.Missing",
  "presence.Extra",
  "presence.Empty",
  "convention.ExactNeighbor",
  "convention.PooledNeighbor",
  "convention.RunShape",
  "convention.Placement",
  "convention.Rarity",
  "convention.Casing",
  "convention.WordLength",
  "convention.Doubled",
  "convention.LetterRun",
  "convention.SentenceStart",
  "convention.BookRate",
  "sourceCopy",
  "lengthProportionality",
