/** A finding's code; a convention finding's channel is on its pattern, so
 * pass the snapshot's `patterns()`. Total: the reader refuses a class, kind,
 * channel or pattern index outside its tables. */
export function codeOf(finding: Finding, patterns: readonly Pattern[]): SousCode {
  switch (finding.kind) {
    case "Hygiene":
      return `hygiene.${finding.hygiene.class}`;
    case "Presence":
      return `presence.${finding.presence.kind}`;
    case "Convention":
      return `convention.${patterns[finding.convention.pattern]!.channel}`;
    case "SourceCopy":
      return "sourceCopy";
    case "LengthProportionality":
      return "lengthProportionality";
  }
}

export class FindingsSnapshotError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "FindingsSnapshotError";
  }
}

interface BookEntry {
  readonly key: string;
  /** The host's opaque book id, unique where `key` need not be. */
  readonly id: string;
  readonly length: number;
  readonly offset: number;
  readonly count: number;
}

function fail(message: string): never {
  throw new FindingsSnapshotError(message);
}

function asDataView(source: ByteSource): DataView {
  if (ArrayBuffer.isView(source)) {
    return new DataView(source.buffer, source.byteOffset, source.byteLength);
  }
  if (source instanceof ArrayBuffer) {
    return new DataView(source);
  }
  return fail("findings buffer is not an ArrayBuffer or view");
}

function u32(view: DataView, at: number): number {
  return view.getUint32(at, true);
}

function checkKey(view: DataView, at: number): string {
  const bytes: number[] = [];
  for (let i = 0; i < 3; i += 1) {
    const byte = view.getUint8(at + i);
    if (byte < 0x20 || byte > 0x7e) {
      return fail(`book key contains a non-printable ASCII byte at ${at + i}`);
    }
    bytes.push(byte);
  }
  if (view.getUint8(at + 3) !== 0) {
    return fail(`book key at ${at} is missing its terminator`);
  }
  return String.fromCharCode(...bytes);
}

const UTF8 = new TextDecoder("utf-8", { fatal: true });

/** One `u16` length-prefixed UTF-8 id, with the offset just past it. */
function readId(view: DataView, offset: number, book: number): [string, number] {
  if (offset + ID_PREFIX_BYTES > view.byteLength) {
    return fail(`book ${book} id runs past the corpus buffer`);
  }
  const length = view.getUint16(offset, true);
  const end = offset + ID_PREFIX_BYTES + length;
  if (end > view.byteLength) {
    return fail(`book ${book} id runs past the corpus buffer`);
  }
  const bytes = new Uint8Array(view.buffer, view.byteOffset + offset + ID_PREFIX_BYTES, length);
  try {
    return [UTF8.decode(bytes), end];
  } catch {
    return fail(`book ${book} id is not valid UTF-8`);
  }
}

function isScalar(raw: number): boolean {
  return raw === PATTERN_DIGIT_GLYPH || (raw <= 0x10ffff && (raw < 0xd800 || raw > 0xdfff));
}

/** A letter, a space, or a digit: no rarity usual names one, or is given for one. */
function isUnmarked(raw: number): boolean {
  return raw === PATTERN_DIGIT_GLYPH || /[\p{Alphabetic}\p{White_Space}\p{Nd}]/u.test(String.fromCodePoint(raw));
}

/** A row's usual lanes as its channel reads them; `null` for a value outside
 * the channel's domain or a lane it does not use holding anything. Whether a
 * rarity's usual shares the glyph's pool or skeleton is the Rust decoder's
 * check alone: neither table is in this reader. */
function readUsual(
  channel: Channel,
  glyph: number,
  denominator: number,
  usual: number,
  count: number,
  other: number,
  lookalike: boolean,
  facing: number,
  directionless: boolean,
  inside: boolean,
): Usual | null {
  if (lookalike && channel !== "Rarity") {
    return null;
  }
  if (channel === "ExactNeighbor") {
    const faced = readFacing(facing);
    const valid = isScalar(usual) && count <= denominator && faced !== undefined && (faced !== null) === directionless;
    return valid ? { kind: "ExactNeighbor", neighbor: usual, count, reversed: other, facing: faced } : null;
  }
  if (facing !== 0) {
    return null;
  }
  // `other` is the book, which the key already read.
  if (channel === "BookRate") {
    return usual <= 10000 && count >= BOOK_RATE_MIN_BOOKS - 1
      ? { kind: "BookRate", baselineBp: usual, otherBooks: count }
      : null;
  }
  if (other !== 0 || count > denominator) {
    return null;
  }
  if (channel === "Placement" && inside) {
    return usual === 0 && count === 0 ? { kind: "None" } : null;
  }
  if (channel === "Placement") {
    const outer = OUTER_CLASSES[usual];
    return outer === undefined || outer === "Edge" ? null : { kind: "Placement", class: outer, count };
  }
  if (channel === "RunShape") {
    const high = usual >> 4;
    const low = usual & 0x0f;
    return usual > 0xff || high > 1 || low === 0 || low > RUN_BUCKETS ? null : { kind: "RunShape", pure: high === 1, bucket: low, count };
  }
  if (channel === "Rarity") {
    if (usual === 0) {
      return count === 0 && !lookalike ? { kind: "Rarity", glyph: null, count, lookalike } : null;
    }
    const valid = isScalar(usual) && usual !== glyph && !isUnmarked(usual) && !isUnmarked(glyph) && count > 0;
    return valid ? { kind: "Rarity", glyph: usual, count, lookalike } : null;
  }
  if (channel === "Casing") {
    const form = CASING_FORMS[usual];
    return form === undefined || form === "Uncased" ? null : { kind: "Casing", form, count };
  }
  return usual === 0 && count === 0 ? { kind: "None" } : null;
}

/** One 36-byte pattern row, refusing every value the encoder cannot write. */
function readPattern(view: DataView, at: number, row: number, bookCount: number): Pattern {
  const flags = view.getUint8(at + PATTERN_FLAGS_OFFSET);
  if ((flags & ~PATTERN_LOOKALIKE) !== 0) {
    return fail(`pattern row ${row} has an invalid flags`);
  }
  const rawGlyph = u32(view, at + PATTERN_GLYPH_OFFSET);
  const neighbor = u32(view, at + PATTERN_NEIGHBOR_OFFSET);
  const channel = CHANNELS[view.getUint8(at + PATTERN_CHANNEL_OFFSET)];
  if (channel === undefined) {
    return fail(`pattern row ${row} has an invalid channel`);
  }
  // Bytes 0..8 are a u64 word hash on a word channel, so no scalar check
  // applies there.
  const word = channel === "Casing" || channel === "WordLength" || channel === "Doubled";
  const glyph = word ? 0 : rawGlyph;
  if (!word && !isScalar(glyph)) {
    return fail(`pattern row ${row} has an invalid glyph`);
  }
  const raw = view.getUint8(at + PATTERN_KEY_OFFSET);
  const high = raw >> 4;
  const low = raw & 0x0f;
  let key: PatternKey;
  if (word) {
    const hash = (BigInt(neighbor) << 32n) | BigInt(rawGlyph);
    if (channel === "WordLength") {
      key = { kind: "WordLength", hash, sigma: raw };
    } else if (channel === "Doubled") {
      if (raw > 1) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "Doubled", hash, separated: raw === 1 };
    } else {
      const form = CASING_FORMS[raw];
      if (form === undefined || form === "Uncased") {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "Casing", hash, form };
    }
  } else if (channel === "ExactNeighbor") {
    if (raw !== 0) {
      return fail(`pattern row ${row} has an invalid key`);
    }
    if (!isScalar(neighbor)) {
      return fail(`pattern row ${row} has an invalid neighbor`);
    }
    key = {
      kind: "ExactNeighbor",
      neighbor,
      directionless: isDirectionlessQuote(glyph) || isDirectionlessQuote(neighbor),
    };
  } else {
    if (neighbor !== 0) {
      return fail(`pattern row ${row} has an invalid neighbor`);
    }
    if (channel === "PooledNeighbor") {
      const pool = POOLS[raw];
      if (pool === undefined) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "PooledNeighbor", pool };
    } else if (channel === "RunShape") {
      if (high > 1 || low === 0 || low > RUN_BUCKETS) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "RunShape", pure: high === 1, bucket: low };
    } else if (channel === "Placement" || channel === "BookRate") {
      const outer = OUTER_CLASSES[low];
      const inside = channel === "Placement" && high === 2 && outer === "Letter";
      if ((high > 1 && !inside) || outer === undefined || (channel === "BookRate" && outer === "Edge")) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      const side = high === 1 ? "next" : "prev";
      if (channel === "Placement") {
        key = { kind: "Placement", side: inside ? "both" : side, class: outer };
      } else {
        const book = u32(view, at + PATTERN_OTHER_COUNT_OFFSET);
        if (book >= bookCount) {
          return fail(`pattern row ${row} has an invalid other_count`);
        }
        key = { kind: "BookRate", side, class: outer, book };
      }
    } else if (channel === "LetterRun") {
      // A real scalar in the glyph field, and the key byte is the run length.
      if (raw < LETTER_RUN_MIN || raw > LETTER_RUN_MAX) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "LetterRun", length: raw };
    } else if (channel === "SentenceStart") {
      // The glyph is the whole claim: a lowercase letter after a glyph this
      // corpus almost always capitalizes after.
      if (raw !== 0) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "SentenceStart" };
    } else {
      if (raw !== 0) {
        return fail(`pattern row ${row} has an invalid key`);
      }
      key = { kind: "Rarity" };
    }
  }
  const rawBand = view.getUint8(at + PATTERN_BAND_OFFSET);
  let band: number | null;
  if (channel === "Rarity" || channel === "BookRate") {
    if (rawBand !== PATTERN_BAND_NONE) {
      return fail(`pattern row ${row} has an invalid band`);
    }
    band = null;
  } else {
    if (rawBand >= BAND_STEPS) {
      return fail(`pattern row ${row} has an invalid band`);
    }
    band = rawBand;
  }
  const shareBp = view.getUint16(at + PATTERN_SHARE_OFFSET, true);
  const numerator = u32(view, at + PATTERN_NUMERATOR_OFFSET);
  const denominator = u32(view, at + PATTERN_DENOMINATOR_OFFSET);
  if (numerator > denominator) {
    return fail(`pattern row ${row} has an invalid numerator`);
  }
  // The same fraction the producer computes, from the same clamped pair: a
  // row whose share does not follow from its own counts is refused, not
  // reported.
  const expected =
    denominator === 0
      ? 0
      : Math.min(Math.floor((numerator * 10000) / denominator), 10000);
  if (shareBp > 10000 || shareBp !== expected) {
    return fail(`pattern row ${row} has an invalid share`);
  }
  const books = view.getUint8(at + PATTERN_BOOKS_OFFSET);
  if (books > bookCount || (books === 0 && numerator > 0) || (channel === "BookRate" && books !== 1)) {
    return fail(`pattern row ${row} has an invalid books`);
  }
  const usual = readUsual(
    channel,
    glyph,
    denominator,
    u32(view, at + PATTERN_USUAL_OFFSET),
    u32(view, at + PATTERN_USUAL_COUNT_OFFSET),
    u32(view, at + PATTERN_OTHER_COUNT_OFFSET),
    (flags & PATTERN_LOOKALIKE) !== 0,
    view.getUint8(at + PATTERN_FACING_OFFSET),
    key.kind === "ExactNeighbor" && key.directionless,
    key.kind === "Placement" && key.side === "both",
  );
  if (usual === null) {
    return fail(`pattern row ${row} has an invalid usual`);
  }
  return {
    glyph,
    channel,
    key,
    band,
    numerator,
    denominator,
    shareBp,
    books,
    usual,
  };
}

/** Where one cluster entry's fields are, and the offset just past it. */
interface ClusterEntry {
  readonly at: number;
  readonly end: number;
}

/** Walks the cluster section, refusing every entry the encoder cannot write,
 * and returns each pattern's entries. */
function readClusterSection(
  view: DataView,
  start: number,
  count: number,
  patternStart: number,
  patternCount: number,
): [Map<number, ClusterEntry[]>, number] {
  const byPattern = new Map<number, ClusterEntry[]>();
  let at = start;
  let last: [number, number] | null = null;
  for (let entry = 0; entry < count; entry += 1) {
    const bad = (field: string): never => fail(`cluster entry ${entry} has an invalid ${field}`);
    if (at + CLUSTER_ENTRY_BYTES > view.byteLength) {
      return bad("length");
    }
    const pattern = view.getUint16(at + CLUSTER_PATTERN_OFFSET, true);
    const atoms = view.getUint8(at + CLUSTER_ATOM_COUNT_OFFSET);
    const flags = view.getUint8(at + CLUSTER_FLAGS_OFFSET);
    const occurrences = u32(view, at + CLUSTER_COUNT_OFFSET);
    const end = at + CLUSTER_ENTRY_BYTES + 4 * atoms;
    if (end > view.byteLength) {
      return bad("length");
    }
    if ((flags & ((1 << CLUSTER_FACING_SHIFT) - 1) & ~(CLUSTER_RECURRING | CLUSTER_TRUNCATED)) !== 0) {
      return bad("flags");
    }
    const facing = readFacing(flags >> CLUSTER_FACING_SHIFT);
    if (facing === undefined) {
      return bad("facing");
    }
    const scalars: number[] = [];
    for (let atom = 0; atom < atoms; atom += 1) {
      const raw = u32(view, at + CLUSTER_ENTRY_BYTES + 4 * atom);
      if (!isScalar(raw)) {
        return bad("atoms");
      }
      scalars.push(raw);
    }
    if (pattern >= patternCount) {
      return bad("pattern");
    }
    const row = patternStart + pattern * PATTERN_ROW_LEN;
    if (CHANNELS[view.getUint8(row + PATTERN_CHANNEL_OFFSET)] !== "RunShape") {
      return bad("pattern");
    }
    const glyph = u32(view, row + PATTERN_GLYPH_OFFSET);
    const key = view.getUint8(row + PATTERN_KEY_OFFSET);
    const [pure, bucket] = [key >> 4 === 1, key & 0x0f];
    const stored =
      atoms > 0 && atoms <= CLUSTER_ATOMS && occurrences > 0 && scalars.every((atom) => atom !== PATTERN_DIGIT_GLYPH);
    const quoted = scalars.some(isDirectionlessQuote);
    const shaped =
      (flags & CLUSTER_TRUNCATED) !== 0
        ? atoms === CLUSTER_ATOMS && bucket === RUN_BUCKETS && (facing !== null || !quoted)
        : scalars.includes(glyph) &&
          scalars.every((atom) => atom === glyph) === pure &&
          Math.min(atoms, RUN_BUCKETS) === bucket &&
          (facing !== null) === quoted;
    if (!stored || !shaped) {
      return bad("atoms");
    }
    if (last !== null) {
      const [held, heldCount]: [number, number] = last;
      const run = byPattern.get(pattern)?.length ?? 0;
      if (pattern < held || (pattern === held && (occurrences > heldCount || run === CLUSTERS_PER_ROW))) {
        return bad("order");
      }
    }
    last = [pattern, occurrences];
    const entries = byPattern.get(pattern) ?? [];
    entries.push({ at, end });
    byPattern.set(pattern, entries);
    at = end;
  }
  return [byPattern, at];
}

function readCluster(view: DataView, entry: ClusterEntry): Cluster {
  const atoms = view.getUint8(entry.at + CLUSTER_ATOM_COUNT_OFFSET);
  const flags = view.getUint8(entry.at + CLUSTER_FLAGS_OFFSET);
  const scalars = Array.from({ length: atoms }, (_, atom) =>
    u32(view, entry.at + CLUSTER_ENTRY_BYTES + 4 * atom),
  );
  return {
    text: String.fromCodePoint(...scalars),
    count: u32(view, entry.at + CLUSTER_COUNT_OFFSET),
    recurring: (flags & CLUSTER_RECURRING) !== 0,
    truncated: (flags & CLUSTER_TRUNCATED) !== 0,
    directionless: scalars.some(isDirectionlessQuote),
    facing: readFacing(flags >> CLUSTER_FACING_SHIFT) ?? null,
  };
}

/** The terminal section, refusing every entry the encoder cannot write:
 * strictly ascending by glyph then context, `upper` at most `cased`, and
 * `cased` never zero. */
function readTerminalSection(view: DataView, start: number, count: number): [Terminal[], number] {
  const terminals: Terminal[] = [];
  let last = -1;
  for (let entry = 0; entry < count; entry += 1) {
    const at = start + entry * TERMINAL_ENTRY_BYTES;
    const bad = (field: string): never => fail(`terminal entry ${entry} has an invalid ${field}`);
    if (at + TERMINAL_ENTRY_BYTES > view.byteLength) {
      return bad("length");
    }
    const glyph = u32(view, at + TERMINAL_GLYPH_OFFSET);
    const context = view.getUint8(at + TERMINAL_CONTEXT_OFFSET);
    const upper = u32(view, at + TERMINAL_UPPER_OFFSET);
    const cased = u32(view, at + TERMINAL_CASED_OFFSET);
    if (glyph === PATTERN_DIGIT_GLYPH || !isScalar(glyph)) {
      return bad("glyph");
    }
    if ((context & ~(TERMINAL_QUOTED | TERMINAL_BRACKETED)) !== 0) {
      return bad("context");
    }
    for (let pad = TERMINAL_CONTEXT_OFFSET + 1; pad < TERMINAL_UPPER_OFFSET; pad += 1) {
      if (view.getUint8(at + pad) !== 0) {
        return bad("pad");
      }
    }
    if (cased === 0) {
      return bad("cased");
    }
    if (upper > cased) {
      return bad("upper");
    }
    const order = glyph * 4 + context;
    if (order <= last) {
      return bad("order");
    }
    last = order;
    terminals.push({
      glyph,
      quoted: (context & TERMINAL_QUOTED) !== 0,
      bracketed: (context & TERMINAL_BRACKETED) !== 0,
      upper,
      cased,
    });
  }
  return [terminals, start + count * TERMINAL_ENTRY_BYTES];
}

function readReasons(bits: number): readonly ConventionReason[] {
  if (bits === 0) {
    return fail("a convention row carries at least one reason");
  }
  if ((bits & ~((1 << CONVENTION_REASONS.length) - 1)) !== 0) {
    return fail(`unknown convention reasons 0x${bits.toString(16).padStart(4, "0")}`);
  }
  return CONVENTION_REASONS.filter((_, bit) => (bits & (1 << bit)) !== 0);
}

/** Lane A of the hygiene row at `at`: the class byte and the site byte. */
function readHygieneLaneA(
  view: DataView,
  at: number,
): Pick<HygieneDigest, "class" | "placement" | "anchor" | "oneUnit" | "loneIsSilent"> {
  const classIndex = view.getUint8(at + RECORD_BOOK_SCOPE_OFFSET);
  const hygieneClass = HYGIENE_CLASSES[classIndex];
  if (hygieneClass === undefined) {
    return fail(`unknown hygiene class ${classIndex}`);
  }
  const site = view.getUint8(at + RECORD_BOOK_SCOPE_OFFSET + 1);
  const placement = HYGIENE_PLACEMENTS[site & 0b111];
  if (placement === undefined || (site & 0x80) !== 0) {
    return fail(`unknown hygiene site byte 0x${site.toString(16).padStart(2, "0")}`);
  }
  return {
    class: hygieneClass,
    placement,
    anchor: HYGIENE_ANCHORS[(site >> HYGIENE_SITE_ANCHOR_SHIFT) & 0b11],
    oneUnit: (site & HYGIENE_SITE_ONE_UNIT) !== 0,
    loneIsSilent: (site & HYGIENE_SITE_LONE_IS_SILENT) !== 0,
  };
}

function signedDeviation(view: DataView, at: number): number | null {
  const raw = view.getInt16(at, true);
  return raw === -0x8000 ? null : raw / 256;
}

export class BookView {
  readonly #view: DataView;
  readonly #entry: BookEntry;
  readonly #index: number;
  readonly #patternCount: number;

  constructor(view: DataView, entry: BookEntry, index: number, patternCount: number) {
    this.#view = view;
    this.#entry = entry;
    this.#index = index;
    this.#patternCount = patternCount;
  }

  get key(): string {
    return this.#entry.key;
  }

  /** The host id this book was published under. */
  get id(): string {
    return this.#entry.id;
  }

  get index(): number {
    return this.#index;
  }

  /** Number of lazy finding rows in this book. */
  get length(): number {
    return this.#entry.count;
  }

  /** Published coordinate extent for this book. */
  get publishedLength(): number {
    return this.#entry.length;
  }

  get count(): number {
    return this.#entry.count;
  }

  at(row: number): Finding {
    if (!Number.isSafeInteger(row) || row < 0 || row >= this.#entry.count) {
      return fail(`finding row ${row} is outside book ${this.#index}`);
    }
    const at = this.#entry.offset + row * RECORD_LEN;
    const from = u32(this.#view, at + RECORD_FROM_OFFSET);
    const to = u32(this.#view, at + RECORD_TO_OFFSET);
    const bookIdx = this.#view.getUint16(at + RECORD_BOOK_INDEX_OFFSET, true);
    if (bookIdx !== this.#index) {
      return fail(`finding row ${row} carries book index ${bookIdx}, expected ${this.#index}`);
    }
    const code = this.#view.getUint8(at + RECORD_CODE_OFFSET);
    if (code !== 0 && code !== 1 && code !== 2 && code !== 3 && code !== 4) {
      return fail(`unknown finding rule code ${code}`);
    }
    const flags = this.#view.getUint8(at + RECORD_FLAGS_OFFSET);
    if ((flags & ~1) !== 0) {
      return fail(`unknown finding flags 0x${flags.toString(16).padStart(2, "0")}`);
    }
    if (from > to) {
      return fail(`reversed finding span ${from}..${to}`);
    }
    if (to > this.#entry.length) {
      return fail(`finding span ${from}..${to} exceeds book length ${this.#entry.length}`);
    }
    const saturated = (flags & 1) !== 0;
    if (code === 1) {
      const laneA = readHygieneLaneA(this.#view, at);
      const run = this.#view.getInt16(at + RECORD_PROJECT_SCOPE_OFFSET, true);
      if (run < 1) {
        return fail("hygiene run length must be at least 1");
      }
      if (saturated && run !== 0x7fff) {
        return fail("saturated hygiene run must read back as 0x7fff");
      }
      return {
        kind: "Hygiene",
        from,
        to,
        bookIdx,
        hygiene: { ...laneA, run, saturated },
      };
    }
    if (code === 4) {
      const kindIndex = this.#view.getInt16(at + RECORD_BOOK_SCOPE_OFFSET, true);
      const presenceKind = PRESENCE_KINDS[kindIndex];
      if (presenceKind === undefined) {
        return fail(`unknown presence kind ${kindIndex}`);
      }
      const keys = this.#view.getInt16(at + RECORD_PROJECT_SCOPE_OFFSET, true);
      if (keys < 1) {
        return fail("a presence row covers at least one key");
      }
      if (saturated && keys !== 0x7fff) {
        return fail("saturated presence key count must read back as 0x7fff");
      }
      return { kind: "Presence", from, to, bookIdx, presence: { kind: presenceKind, keys, saturated } };
    }
    if (code === 3) {
      const run = this.#view.getInt16(at + RECORD_BOOK_SCOPE_OFFSET, true);
      const eligible = this.#view.getInt16(at + RECORD_PROJECT_SCOPE_OFFSET, true);
      if (run < 1 || eligible < run) {
        return fail(`a source-copy run of ${run} in a unit of ${eligible} eligible words`);
      }
      if (saturated && run !== 0x7fff && eligible !== 0x7fff) {
        return fail("a saturated source-copy row clamps a lane to 0x7fff");
      }
      return { kind: "SourceCopy", from, to, bookIdx, sourceCopy: { run, eligible, saturated } };
    }
    if (code === 2) {
      if (saturated) {
        return fail("a convention row is never saturated");
      }
      const pattern = this.#view.getUint16(at + RECORD_BOOK_SCOPE_OFFSET, true);
      if (pattern >= this.#patternCount) {
        return fail(`book ${this.#index} row ${row} names pattern ${pattern} in a table of ${this.#patternCount}`);
      }
      const reasons = readReasons(this.#view.getUint16(at + RECORD_PROJECT_SCOPE_OFFSET, true));
      return { kind: "Convention", from, to, bookIdx, convention: { pattern, reasons } };
    }
    return {
      kind: "LengthProportionality",
      from,
      to,
      bookIdx,
      digest: {
        bookScope: signedDeviation(this.#view, at + RECORD_BOOK_SCOPE_OFFSET),
        projectScope: signedDeviation(this.#view, at + RECORD_PROJECT_SCOPE_OFFSET),
        saturated,
      },
    };
  }
}

export type HygieneScope = "book" | "project";

/** `book` is `null` in project scope. */
export interface HygieneGroupKey {
  readonly book: number | null;
  readonly class: HygieneClass;
  readonly placement: HygienePlacement;
}

/** onion's edit shape with an empty insert, in the publication's coordinates. */
export interface HygieneDeletion {
  readonly bookIdx: number;
  readonly from: number;
  readonly to: number;
}

const REMOVED_BESIDE: Readonly<Record<string, readonly HygienePlacement[]>> = {
  NoBreakSpace: ["BesideSpace", "AtEdge", "Alone"],
  MisplacedFormat: ["BesideSpace", "BesidePunctuation", "AtEdge", "Alone"],
};

/** The fix table: `galley/sous-messages.md`, "Hygiene fixes". */
function hygieneAction(digest: HygieneDigest): "remove" | "keepOne" | null {
  if (digest.class === "C0Control" || digest.class === "Delete" || digest.class === "Noncharacter") {
    return "remove";
  }
  const removable = REMOVED_BESIDE[digest.class];
  if (removable === undefined) {
    return null;
  }
  if (digest.loneIsSilent) {
    return "keepOne";
  }
  return removable.includes(digest.placement) ? "remove" : null;
}

/** The one deletion that fixes this row, or `null` when none is certain:
 * a class the table does not fix, a run that is not one piece of its span,
 * or a run whose UTF-16 length the row cannot say. */
export function hygieneFix(finding: HygieneFinding, coordinateSpace: CoordinateSpace): HygieneDeletion | null {
  const digest = finding.hygiene;
  const action = hygieneAction(digest);
  if (action === null || digest.anchor === "Neither") {
    return null;
  }
  const { bookIdx, from, to } = finding;
  if (action === "remove" && digest.anchor === "Exact") {
    return { bookIdx, from, to };
  }
  if (coordinateSpace !== "utf16" || !digest.oneUnit || digest.saturated) {
    return null;
  }
  const run = digest.run;
  const atEnd = digest.anchor === "AtEnd";
  const [start, end] = atEnd ? [to - run, to] : [from, from + run];
  const kept = action === "keepOne" ? start + 1 : start;
  return kept < end ? { bookIdx, from: kept, to: end } : null;
}

/** One habit: every hygiene row of one (book or project, class, placement).
 * Holds row positions only; rows decode when asked for. */
export class HygieneGroup {
  readonly key: HygieneGroupKey;
  readonly #rows: Uint32Array;
  readonly #book: (index: number) => BookView;
  readonly #coordinateSpace: CoordinateSpace;

  constructor(
    key: HygieneGroupKey,
    rows: Uint32Array,
    book: (index: number) => BookView,
    coordinateSpace: CoordinateSpace,
  ) {
    this.key = key;
    this.#rows = rows;
    this.#book = book;
    this.#coordinateSpace = coordinateSpace;
  }

  get count(): number {
    return this.#rows.length / 2;
  }

  /** `[bookIdx, row]` per member, in publication order. */
  rows(): Array<[number, number]> {
    return Array.from({ length: this.count }, (_, index) => [this.#rows[2 * index], this.#rows[2 * index + 1]]);
  }

  at(index: number): HygieneFinding {
    if (!Number.isSafeInteger(index) || index < 0 || index >= this.count) {
      return fail(`group member ${index} is outside a group of ${this.count}`);
    }
    return this.#book(this.#rows[2 * index]).at(this.#rows[2 * index + 1]) as HygieneFinding;
  }

  /** Every member's deletion, last first within a book, so they apply in
   * order. `null` when no member has one. */
  fix(): HygieneDeletion[] | null {
    const out: HygieneDeletion[] = [];
    for (let index = 0; index < this.count; index++) {
      const deletion = hygieneFix(this.at(index), this.#coordinateSpace);
      if (deletion !== null) {
        out.push(deletion);
      }
    }
    if (out.length === 0) {
      return null;
    }
    return out.sort((a, b) => a.bookIdx - b.bookIdx || b.from - a.from);
  }
}

export class FindingsSnapshot {
  readonly #view: DataView;
  readonly #entries: readonly BookEntry[];
  readonly #byKey: ReadonlyMap<string, number>;
  readonly #byId: ReadonlyMap<string, number>;
  readonly #patternStart: number;
  readonly #patternCount: number;
  readonly #clusters: ReadonlyMap<number, readonly ClusterEntry[]>;
  readonly #terminals: readonly Terminal[];
  readonly snapshotId: Uint8Array;
  readonly coordinateSpace: CoordinateSpace;

  private constructor(
    view: DataView,
    entries: readonly BookEntry[],
    snapshotId: Uint8Array,
    coordinateSpace: CoordinateSpace,
    patternStart: number,
    patternCount: number,
    clusters: ReadonlyMap<number, readonly ClusterEntry[]>,
    terminals: readonly Terminal[],
  ) {
    this.#view = view;
    this.#entries = entries;
    this.#patternStart = patternStart;
    this.#patternCount = patternCount;
    this.#clusters = clusters;
    this.#terminals = terminals;
    // First position wins: two ids may publish the same `\id`.
    this.#byKey = new Map([...entries].reverse().map((entry, at) => [entry.key, entries.length - 1 - at]));
    this.#byId = new Map(entries.map((entry, index) => [entry.id, index]));
    this.snapshotId = snapshotId;
    this.coordinateSpace = coordinateSpace;
  }

  static open(source: ByteSource): FindingsSnapshot {
    const view = asDataView(source);
    if (view.byteLength < HEADER_BYTES) {
      return fail(`corpus buffer is ${view.byteLength} bytes; header is ${HEADER_BYTES}`);
    }
    if (u32(view, HEADER_MAGIC_OFFSET) !== MAGIC) {
      return fail("unknown corpus magic");
    }
    if (u32(view, HEADER_VERSION_OFFSET) !== FORMAT_VERSION) {
      return fail(`unsupported corpus format version ${u32(view, HEADER_VERSION_OFFSET)}`);
    }
    const flags = u32(view, HEADER_FLAGS_OFFSET);
    if (flags !== 0 && flags !== FLAG_UTF16) {
      return fail(`unknown corpus flags 0x${flags.toString(16)}`);
    }
    const coordinateSpace: CoordinateSpace = flags === FLAG_UTF16 ? "utf16" : "utf8";
    const bookCount = u32(view, HEADER_BOOK_COUNT_OFFSET);
    if (bookCount > 0x10000) {
      return fail(`corpus has ${bookCount} books; maximum is 65536`);
    }
    if (u32(view, HEADER_RECORD_LEN_OFFSET) !== RECORD_LEN) {
      return fail(`record stride is ${u32(view, HEADER_RECORD_LEN_OFFSET)}, expected ${RECORD_LEN}`);
    }
    const totalFindings = u32(view, HEADER_TOTAL_FINDINGS_OFFSET);
    const patternCount = u32(view, HEADER_PATTERN_COUNT_OFFSET);
    if (patternCount > 0xffff) {
      return fail(`corpus declares ${patternCount} patterns; maximum is 65535`);
    }
    const snapshotId = new Uint8Array(view.buffer, view.byteOffset + HEADER_SNAPSHOT_ID_OFFSET, 16).slice();
    const idStart = HEADER_BYTES + bookCount * DIRECTORY_ENTRY_BYTES;
    if (idStart > view.byteLength) {
      return fail("book directory exceeds corpus buffer");
    }

    // The id string table, in directory order: each offset must be the running
    // cursor, so the strings cannot overlap, reorder, or hide bytes.
    const ids: string[] = [];
    const seenIds = new Set<string>();
    let idCursor = idStart;
    for (let index = 0; index < bookCount; index += 1) {
      const at = HEADER_BYTES + index * DIRECTORY_ENTRY_BYTES + DIRECTORY_ID_OFFSET;
      const offset = u32(view, at);
      if (offset !== idCursor) {
        return fail(`book ${index} id starts at ${offset}, expected ${idCursor}`);
      }
      const [id, end] = readId(view, offset, index);
      if (seenIds.has(id)) {
        return fail(`book ${index} repeats a host id already published`);
      }
      seenIds.add(id);
      ids.push(id);
      idCursor = end;
    }
    const patternStart =
      idStart + Math.ceil((idCursor - idStart) / SECTION_ALIGNMENT) * SECTION_ALIGNMENT;
    if (patternStart > view.byteLength) {
      return fail("book id table exceeds corpus buffer");
    }
    if (u32(view, HEADER_PATTERN_OFFSET_OFFSET) !== patternStart) {
      return fail(
        `pattern table starts at ${u32(view, HEADER_PATTERN_OFFSET_OFFSET)}, expected ${patternStart}`,
      );
    }
    const patternEnd = patternStart + patternCount * PATTERN_ROW_LEN;
    if (patternEnd > view.byteLength) {
      return fail("pattern table exceeds corpus buffer");
    }
    for (let row = 0; row < patternCount; row += 1) {
      readPattern(view, patternStart + row * PATTERN_ROW_LEN, row, bookCount);
    }
    if (u32(view, HEADER_CLUSTER_OFFSET_OFFSET) !== patternEnd) {
      return fail(
        `cluster section starts at ${u32(view, HEADER_CLUSTER_OFFSET_OFFSET)}, expected ${patternEnd}`,
      );
    }
    const [clusters, clusterEnd] = readClusterSection(
      view,
      patternEnd,
      u32(view, HEADER_CLUSTER_COUNT_OFFSET),
      patternStart,
      patternCount,
    );

    if (u32(view, HEADER_TERMINAL_OFFSET_OFFSET) !== clusterEnd) {
      return fail(
        `terminal section starts at ${u32(view, HEADER_TERMINAL_OFFSET_OFFSET)}, expected ${clusterEnd}`,
      );
    }
    const [terminals, terminalEnd] = readTerminalSection(
      view,
      clusterEnd,
      u32(view, HEADER_TERMINAL_COUNT_OFFSET),
    );

    const entries: BookEntry[] = [];
    let cursor = terminalEnd;
    let totalSeen = 0;
    for (let index = 0; index < bookCount; index += 1) {
      const at = HEADER_BYTES + index * DIRECTORY_ENTRY_BYTES;
      const key = checkKey(view, at + DIRECTORY_KEY_OFFSET);
      const length = u32(view, at + DIRECTORY_LENGTH_OFFSET);
      const offset = u32(view, at + DIRECTORY_SECTION_OFFSET);
      const count = u32(view, at + DIRECTORY_FINDING_COUNT_OFFSET);
      if (offset !== cursor) {
        return fail(`book ${index} section starts at ${offset}, expected ${cursor}`);
      }
      const end = offset + count * RECORD_LEN;
      if (!Number.isSafeInteger(end) || end > view.byteLength) {
        return fail(`book ${index} section exceeds corpus buffer`);
      }
      entries.push({ key, id: ids[index], length, offset, count });
      cursor = end;
      totalSeen += count;
    }
    if (cursor !== view.byteLength) {
      return fail(`corpus has trailing bytes after offset ${cursor}`);
    }
    if (totalSeen !== totalFindings) {
      return fail(`header declares ${totalFindings} findings, directory contains ${totalSeen}`);
    }
    return new FindingsSnapshot(view, entries, snapshotId, coordinateSpace, patternStart, patternCount, clusters, terminals);
  }

  get length(): number {
    return this.#entries.length;
  }

  /** Rows in the publication's pattern table. */
  get patternCount(): number {
    return this.#patternCount;
  }

  /** One pattern row, decoded; a `RunShape` row brings its clusters. */
  pattern(index: number): Pattern {
    if (!Number.isSafeInteger(index) || index < 0 || index >= this.#patternCount) {
      return fail(`pattern ${index} is outside a table of ${this.#patternCount}`);
    }
    const row = readPattern(
      this.#view,
      this.#patternStart + index * PATTERN_ROW_LEN,
      index,
      this.#entries.length,
    );
    if (row.channel !== "RunShape") {
      return row;
    }
    const clusters = (this.#clusters.get(index) ?? []).map((entry) => readCluster(this.#view, entry));
    return { ...row, clusters };
  }

  /** The whole table, in emission order. */
  patterns(): Pattern[] {
    return Array.from({ length: this.#patternCount }, (_, row) => this.pattern(row));
  }

  /** Every mark and context the corpus handed a cased letter off from,
   * ascending by glyph then context. */
  terminals(): readonly Terminal[] {
    return this.#terminals;
  }

  /** What follows `glyph` in one context: after `;` bare, 482 of 4,677 cased
   * handoffs are uppercase. `undefined` when the corpus never handed a cased
   * letter off from it. */
  terminal(glyph: number, context: TerminalContext): Terminal | undefined {
    const wanted = glyph * 4 + (context.quoted ? TERMINAL_QUOTED : 0) + (context.bracketed ? TERMINAL_BRACKETED : 0);
    let [low, high] = [0, this.#terminals.length];
    while (low < high) {
      const middle = (low + high) >> 1;
      const entry = this.#terminals[middle];
      const order = entry.glyph * 4 + (entry.quoted ? TERMINAL_QUOTED : 0) + (entry.bracketed ? TERMINAL_BRACKETED : 0);
      if (order === wanted) {
        return entry;
      }
      if (order < wanted) {
        low = middle + 1;
      } else {
        high = middle;
      }
    }
    return undefined;
  }

  /** By directory position, or the first book carrying that `BookKey`. */
  book(keyOrIndex: string | number): BookView | undefined {
    const index = typeof keyOrIndex === "string" ? this.#byKey.get(keyOrIndex) : keyOrIndex;
    if (index === undefined || !Number.isSafeInteger(index) || index < 0 || index >= this.#entries.length) {
      return undefined;
    }
    return new BookView(this.#view, this.#entries[index], index, this.#patternCount);
  }

  /** Seeks the id string table; ids are unique where keys need not be. */
  bookById(id: string): BookView | undefined {
    const index = this.#byId.get(id);
    return index === undefined ? undefined : this.book(index);
  }

  /** Hygiene rows grouped by (book or project, class, placement), in that
   * order. One pass over two bytes of each row; nothing else decodes. */
  hygieneGroups({ scope }: { scope: HygieneScope }): HygieneGroup[] {
    const members = new Map<number, number[]>();
    for (let book = 0; book < this.#entries.length; book++) {
      const entry = this.#entries[book];
      for (let row = 0; row < entry.count; row++) {
        const at = entry.offset + row * RECORD_LEN;
        if (this.#view.getUint8(at + RECORD_CODE_OFFSET) !== 1) {
          continue;
        }
        const lane = readHygieneLaneA(this.#view, at);
        const scoped = scope === "book" ? book + 1 : 0;
        const key =
          (scoped * HYGIENE_CLASSES.length + HYGIENE_CLASSES.indexOf(lane.class)) * HYGIENE_PLACEMENTS.length +
          HYGIENE_PLACEMENTS.indexOf(lane.placement);
        const list = members.get(key);
        if (list === undefined) {
          members.set(key, [book, row]);
        } else {
          list.push(book, row);
        }
      }
    }
    const book = (index: number) => this.book(index) as BookView;
    return [...members.keys()]
      .sort((a, b) => a - b)
      .map((key) => {
        const placement = key % HYGIENE_PLACEMENTS.length;
        const rest = (key - placement) / HYGIENE_PLACEMENTS.length;
        const hygieneClass = rest % HYGIENE_CLASSES.length;
        const scoped = (rest - hygieneClass) / HYGIENE_CLASSES.length;
        return new HygieneGroup(
          {
            book: scope === "book" ? scoped - 1 : null,
            class: HYGIENE_CLASSES[hygieneClass],
            placement: HYGIENE_PLACEMENTS[placement],
          },
          Uint32Array.from(members.get(key) as number[]),
          book,
          this.coordinateSpace,
        );
      });
  }

  /** Every finding published under one host id, decoded eagerly. */
  findingsFor(id: string): Finding[] {
    const book = this.bookById(id);
    if (book === undefined) {
      return [];
    }
    return Array.from({ length: book.count }, (_, row) => book.at(row));
  }
}
